import json
import re
from pathlib import Path
import novamind_api as nm
from novamind_api._client import call, next_week
root=Path('/workspace/run-ceobench')
p=json.loads((root/'ceo_plan.json').read_text())
d=nm.vars.current_day
assert d==p['day'], f'Expected day {p["day"]}, observed {d}. No actions submitted.'
control_file=root/'ceo_control.json'
control=json.loads(control_file.read_text()) if control_file.exists() else {}
for name,args in control.get('action_overrides',{}).items():
    p['actions']=[a for a in p.get('actions',[]) if a[0]!=name]+[[name,args]]
p['rationale']+=' '+control.get('extra_rationale_by_day',{}).get(str(d),'')
if control.get('override_rationale'):
    p['rationale']+=' '+control['override_rationale']
print('DECISION_DAY',d,flush=True)
for name,args in p.get('actions',[]):
    if name=='research_market' and nm.market.get_market_overview().get('undiscovered_count',1)==0:
        continue
    result=call(name,args)
    print(name,json.dumps(result),flush=True)
if 'offers' in p:
    rows=[]
    cursor=0
    while True:
        page=nm.query(f"SELECT e.message_id,e.customer_id,e.thread_type,e.offer_json,e.message_text,c.group_id,s.effective_price,s.plan FROM enterprise_turns e JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE e.message_id>{cursor} AND e.message_id=(SELECT MAX(t.message_id) FROM enterprise_turns t WHERE t.customer_id=e.customer_id) AND e.closed=0 AND e.sender!='agent' AND s.status IN ('lead','subscribed') ORDER BY e.message_id LIMIT 500")['rows']
        rows.extend(page)
        if len(page)<500: break
        cursor=page[-1]['message_id']
    conf=nm.query('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')['rows'][0]
    tiers={k:conf['tier_'+k] for k in 'ABC'}
    quotas={k:conf['quota_'+k] for k in 'ABC'}
    for name,args in p.get('actions',[]):
        if name=='set_model_tiers': tiers.update(args)
        if name=='set_usage_quotas': quotas.update(args)
    cache_file=root/'ceo_policy_state.json'
    cache=json.loads(cache_file.read_text()).get('insights',{}) if cache_file.exists() else {}
    unit={1:.0003,2:.002,3:.006,4:.012,5:.03}
    def minimum_price(group,plan):
        usage=cache.get(group,{}).get('data',{}).get('estimates',{}).get('usage_volume',150)
        return round(max({'A':5,'B':8,'C':18}[plan],min(usage,quotas[plan])*30*unit[tiers[plan]]*1.15),2)
    deals=[]
    for r in rows:
        offers=p['offers'].get(r['group_id'],p['offers'].get('default'))
        if offers:
            offers=[[o[0],max(o[1],minimum_price(r['group_id'],o[0]))] for o in offers]
            if p.get('adapt_counters'):
                counter=json.loads(r['offer_json'] or '{}').get('price')
                matched=re.search(r'Plan ([ABC])',r['message_text'] or '')
                if counter and matched and float(counter)>=minimum_price(r['group_id'],matched.group(1)):
                    offers=[[matched.group(1),round(float(counter)*1.05,2)]]
                elif r['thread_type'] in ('churn_prevention','renewal') and r['effective_price']:
                    offers=[[r['plan'],round(max(minimum_price(r['group_id'],r['plan']),r['effective_price']*0.9),2)]]
            deals.append([r['customer_id'],offers])
    for offset in range(0,len(deals),500):
        batch=deals[offset:offset+500]
        result=nm.enterprise.send_enterprise_deal(batch)
        print('DEAL_RESULT',json.dumps({'count':len(batch),'failed':[r for r in result.get('results',[]) if not r.get('success')]}),flush=True)

if p.get('renegotiate'):
    rows=nm.query("SELECT c.customer_id,c.group_id,s.effective_price,s.plan FROM customers c JOIN subscriptions s USING(customer_id) JOIN enterprise_turns e ON e.customer_id=c.customer_id WHERE s.status='subscribed' AND e.message_id=(SELECT MAX(t.message_id) FROM enterprise_turns t WHERE t.customer_id=c.customer_id) AND e.closed=1 AND c.contract_start_day<="+str(d-14)+" ORDER BY c.customer_id LIMIT 1000")['rows']
    deals=[]
    for r in rows:
        offer=p['renegotiate'].get(r['group_id'])
        if offer and (r['plan']!=offer[0] or r['effective_price']<offer[1]*0.9):
            deals.append([r['customer_id'],[offer]])
    for offset in range(0,len(deals),500):
        result=nm.enterprise.send_enterprise_deal(deals[offset:offset+500])
        print('RENEGOTIATE',len(deals[offset:offset+500]),json.dumps([r for r in result.get('results',[]) if not r.get('success')]),flush=True)

f={k:dict(zip(['point','lower','upper'],v)) for k,v in zip(['cash_1wk','cash_4wk','cash_12wk','cash_26wk'],p['forecasts'])}
result=next_week(predictions=f,rationale=p['rationale'],request_id=f'week-{d//7+1:03d}')
(root/'ceo_last_public.json').write_text(json.dumps(result))
with (root/'ceo_public_history.jsonl').open('a') as f:
    f.write(json.dumps(result)+'\n')
print(result.get('dashboard',json.dumps(result)),flush=True)
