  "/workspace/run-ceobench/ceo_development_review.py": {
    "type": "add",
    "content": """"Read-only enterprise plan contribution and support-budget review."""
import json
from pathlib import Path
import novamind_api as nm

d = nm.vars.current_day
config = nm.query('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')['rows'][0]
cost = {1: .0003, 2: .002, 3: .006, 4: .012, 5: .03}
rows = nm.query(f"SELECT c.group_id,s.plan,COUNT(*) customers,SUM(s.seat_count) seats,SUM(s.effective_price*s.seat_count) mrr,SUM(u.usage_units) latest_usage FROM customers c JOIN subscriptions s USING(customer_id) LEFT JOIN daily_usage u ON u.customer_id=c.customer_id AND u.day={d} WHERE c.customer_type='large' AND s.status='subscribed' GROUP BY c.group_id,s.plan")['rows']
groups = {}
for r in rows:
    plan = r['plan']
    unit_cost = cost[config['tier_' + plan]]
    r['compute_month_at_latest_day'] = round((r['latest_usage'] or 0) * unit_cost * 30)
    r['compute_month_at_quota'] = round(r['seats'] * config['quota_' + plan] * unit_cost * 30)
    groups.setdefault(r['group_id'], {})[plan] = r
prior = json.loads(Path('ceo_plan.json').read_text())
prior_dev = next(a[1]['targeted_spend'] for a in prior['actions'] if a[0] == 'set_targeted_dev_spend')
print(json.dumps({'day': d, 'last_plan_day': prior['day'], 'last_development_plan': prior.get('development_plans'), 'last_targeted_daily_development': prior_dev, 'enterprise_groups': groups}), flush=True)
queries = {
    'retail_issue_arrivals': f"SELECT open_day,COUNT(*) n FROM issues WHERE open_day>{d-14} AND (group_id IN ('S1','S2','S3') OR group_id LIKE 'D_S%') GROUP BY open_day",
    'open_issues': "SELECT group_id,COUNT(*) n,MAX(days_open) oldest FROM issues WHERE status='open' GROUP BY group_id",
    'service': f'SELECT day,total_usage_units,capacity_units FROM service_day WHERE day>{d-14} ORDER BY day',
}
for name, sql in queries.items():
    print(name, json.dumps(nm.query(sql)['rows']), flush=True)
"
  }
}

