/bin/bash -lc "python - <<'PY'
from ceo_quality_budget import choose_quality_budget

def row(mrr,margin,gap,tier): return dict(mrr=mrr,margin=margin,gap=gap,tier=tier)
p={'A':row(12000000,300000,3.5,4),'B':row(1000000,10000,5,5),'C':row(700000,16000,1,3)}
assert choose_quality_budget(p,'B',378,326000)==('C',4000)
p={'A':row(8000000,100000,2.5,4),'B':row(1000000,10000,5,5),'C':row(300000,-1000,-1,3)}
assert choose_quality_budget(p,'B',378,109000)==('A',5000)
p={'A':row(6000000,100000,-.1,4),'B':row(100000,1000,1,5),'C':row(0,0,-2,3)}
assert choose_quality_budget(p,'B',378,101000)==('B',30000)
p={'A':row(500000,15000,2,4),'B':row(3000000,90000,5,5),'C':row(0,0,-2,3)}
assert choose_quality_budget(p,'B',378,105000,'A')==('A',4000)
p={'A':row(12000000,300000,1.3,4),'B':row(5000000,100000,5,5),'C':row(2000000,50000,.8,3)}
assert choose_quality_budget(p,'B',460,450000)==('C',15000)
assert choose_quality_budget(p,'B',378,-1000)[1]==0
print('6 strategy-only budget checks passed; no simulator calls.')
import json
from pathlib import Path
f=Path('ceo_control.json');c=json.loads(f.read_text());c['plan_contribution_dev']=True;c['ops_resolution_rate']=.55;c['ops_peak_days']=7;c['ops_arrival_buffer']=1.35;assert c['preview_only'];f.write_text(json.dumps(c))
PY"

