"""Strategy-only quality budget arithmetic; no simulator calls."""
import math


def desired_spend(gap):
    return 100000 if gap < .25 else 75000 if gap < .9 else 50000 if gap < 1.6 else 25000 if gap < 2.1 else 5000 if gap < 3 else 0


def choose_quality_budget(plans, premium, day, group_margin, preferred=None):
    candidates = [preferred] if preferred else [p for p, x in plans.items() if x['gap'] > .5]
    if not candidates:
        candidates = [premium]
    choices = []
    for plan in candidates:
        x = plans[plan]
        funded_margin = max(0, x['margin'])
        funded_mrr = x['mrr']
        # A viable premium option can retain an existing lower-tier book at risk.
        if x['tier'] == plans[premium]['tier']:
            for other, y in plans.items():
                if other != plan and y['tier'] < x['tier'] and y['gap'] < .5:
                    funded_margin += max(0, y['margin'])
                    funded_mrr += y['mrr']
        fraction = .5 if x['gap'] < .5 and funded_mrr >= 5000000 and day < 455 else .3
        wanted = desired_spend(x['gap']) if day <= 455 or x['gap'] < 1.2 else 0
        spend = min(wanted, funded_margin * fraction, max(0, group_margin) * fraction)
        choices.append((spend, x['mrr'], x['tier'], plan))
    spend, _, _, plan = max(choices)
    return plan, math.floor(spend / 1000) * 1000

