"""Unactivated strategy arithmetic for a future endgame review; no API calls.

Uses the documented signing-day prorated charge and 30-day billing cycle.
Counts compute on the acceptance day, conservatively. Assumes scheduled
invoices are paid, so this is a cash estimate rather than a retention guarantee.
"""


def invoice_service_days(accept_day, billing_mod30, end_day=500):
    first = (billing_mod30 - accept_day) % 30 or 30
    later_invoices = max(0, (end_day - accept_day - first) // 30 + 1)
    return first + 30 * later_invoices


def terminal_cost_factor(day, billing_mod30, end_day=500, reply_window=7):
