{
  "/workspace/run-ceobench/ceo_enterprise_trial_review.py": {
    "type": "add",
    "content": """"Read-only follow-up for the planned E2 LinkedIn campaign on days 414-420."""
import json
import novamind_api as nm

day = nm.vars.current_day
cohort = "c.group_id='E2' AND c.acquisition_source='linkedin' AND c.created_day>413 AND c.created_day<=420"
queries = {
    'campaign': "SELECT channel_id,group_id,SUM(spend) spend,SUM(leads_generated) leads FROM ad_channel_leads WHERE day>413 AND day<=420 AND group_id='E2' AND channel_id='linkedin' GROUP BY channel_id,group_id",
    'cohort': f"SELECT s.status,s.plan,COUNT(*) customers,SUM(s.seat_count) seats,SUM(s.effective_price*s.seat_count) monthly_revenue FROM customers c JOIN subscriptions s USING(customer_id) WHERE {cohort} GROUP BY s.status,s.plan",
    'latest_threads': f"SELECT e.thread_type,e.sender,e.closed,e.close_reason,COUNT(*) customers FROM customers c JOIN enterprise_turns e USING(customer_id) WHERE {cohort} AND e.message_id=(SELECT MAX(t.message_id) FROM enterprise_turns t WHERE t.customer_id=c.customer_id) GROUP BY e.thread_type,e.sender,e.closed,e.close_reason",
}
print('DAY', day, flush=True)
for name, sql in queries.items():
    print(name, json.dumps(nm.query(sql)['rows']), flush=True)
"
  }
}

