"""Read-only public retail quality, pricing and contribution review."""
import json, re
from pathlib import Path
import novamind_api as nm

root=Path('/workspace/run-ceobench')
state=json.loads((root/'ceo_policy_state.json').read_text())
last=json.loads((root/'ceo_last_public.json').read_text())
d=nm.vars.current_day
assert last['day']==d
q=lambda sql:nm.query(sql)['rows']
quality={}
for line in last['dashboard'].splitlines():
    p=line.split()
    if len(p)>=5 and re.fullmatch(r'(S[123]|E[123]|D_[SE]\d\d)',p[0]):
        quality[p[0]]=[float(x) for x in p[1:4]]
events=q("SELECT day,COUNT(*) n FROM social_media_posts WHERE content LIKE '%ApexSaaS%' OR content LIKE '%RivalTech%' OR content LIKE '%CloudPeak%' OR content LIKE '%QuantumEdge%' OR content LIKE '%NexGen%' GROUP BY day")
complete={}
for r in q("SELECT day,message FROM notifications WHERE type='group_research_complete' ORDER BY day"):
    m=re.search(r'\b(D_[SE]\d\d|[SE][123])\b',r['message'])
    if m: complete[m[1]]=r['day']
conf=q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')[0]
book=q("SELECT c.group_id,s.plan,s.listed_price,COUNT(*) n,SUM(s.effective_price) mrr FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND s.status='subscribed' GROUP BY c.group_id,s.plan,s.listed_price")
usage=q(f"SELECT c.group_id,s.plan,SUM(u.usage_units) usage FROM daily_usage u JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE u.day={d} AND c.customer_type='small' AND s.status='subscribed' GROUP BY c.group_id,s.plan")
churn=q(f"SELECT c.group_id,s.plan,COUNT(*) n FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.customer_type='small' AND s.status='cancelled' AND s.end_day>{d-7} GROUP BY c.group_id,s.plan")
rates=state['event_rates']; median=sorted(rates.values())[len(rates)//2]
unit={1:.0003,2:.002,3:.006,4:.012,5:.03}
out={}
for g,snap in state['insights'].items():
    if snap['data']['segment']!='Individual': continue
    data=snap['data']; asof=snap['asof']; rate=rates.get(g,median)
    if complete.get(g,0)>asof:
        data=nm.market.get_group_insights(g); asof=complete[g]
        ec=sum(x['n'] for x in events if snap['asof']<x['day']<=asof)
        if ec: rate=min(.3,max(.01,(data['estimates']['quality_floor_q_min']-snap['data']['estimates']['quality_floor_q_min']-.005*(asof-snap['asof']))/ec))
    e=data['estimates']; floor=e['quality_floor_q_min']+.005*(d-asof)+rate*sum(x['n'] for x in events if asof<x['day']<=d)
    if asof==snap['asof']: floor+=state.get('floor_bias',{}).get(g,0)
    gap={p:quality[g][i]-floor for i,p in enumerate('ABC')}
    head=max(.01,gap['A']-.15-.5*max(0,1-conf['quota_A']/max(1,e['usage_volume'])))
    a_cost=min(e['usage_volume'],conf['quota_A'])*unit[conf['tier_A']]*30
    affordable=e['willingness_to_pay']*min(.85,.95*head/(head+.25))
    a_price=min(conf['price_A'],max(5,a_cost*1.2+3,affordable))
    discount=conf['price_A']-a_price
    rows=[r for r in book if r['group_id']==g]
    plans={}
    for r in rows:
        v=plans.setdefault(r['plan'],{'n':0,'mrr':0}); v['n']+=r['n'];v['mrr']+=r['mrr']
    for r in usage:
        if r['group_id']==g and r['plan'] in plans: plans[r['plan']]['latest_compute_month']=round(r['usage']*unit[conf['tier_'+r['plan']]]*30)
    out[g]={'asof':asof,'estimated_floor':round(floor,3),'quality_gaps':{p:round(v,3) for p,v in gap.items()},'budget':e['willingness_to_pay'],'estimated_a_price':round(a_price,2),'estimated_a_cost':round(a_cost,2),'a_affordable':round(affordable,2),'existing_a_mrr_change':round(sum(max(0,r['listed_price']-discount)*r['n']-r['mrr'] for r in rows if r['plan']=='A')),'a_listed_cohorts':[r for r in rows if r['plan']=='A'],'plans':plans,'cancellations_last_week':{r['plan']:r['n'] for r in churn if r['group_id']==g}}
print(json.dumps({'day':d,'competitor_events_last_week':[r for r in events if r['day']>d-7],'groups':out},indent=2),flush=True)

