  "/workspace/run-ceobench/ceo_a_model_review.py": {
    "type": "add",
    "content": """"Read-only A-plan quality/compute scenarios from public observations.

These scenarios cap observed usage; they do not predict demand, satisfaction,
retention, or the consequences of lowering quotas. No mutations are submitted.
"""
import json
from pathlib import Path
import novamind_api as nm

d = nm.vars.current_day
q = lambda sql: nm.query(sql)['rows']
config = q('SELECT * FROM config_history ORDER BY day DESC LIMIT 1')[0]
costs = {1: .0003, 2: .002, 3: .006, 4: .012, 5: .03}
cols = ','.join(
    f'SUM(MIN(u.usage_units,{quota}*s.seat_count))*0.03 proposed_daily_cost_q{quota}'
    for quota in [30, 35, 40, 45, 50]
)
rows = q(f"""SELECT c.group_id,c.customer_type,COUNT(*) customers,
    SUM(s.seat_count) seats,SUM(s.effective_price*s.seat_count) mrr,
    SUM(u.usage_units) usage,
    SUM(u.usage_units)*{costs[config['tier_A']]} current_daily_cost,
    SUM(CASE WHEN u.usage_units>=0.95*s.seat_count*{config['quota_A']}
        THEN s.seat_count ELSE 0 END) seats_near_current_quota,
    {cols}
    FROM customers c JOIN subscriptions s USING(customer_id)
    JOIN daily_usage u ON u.customer_id=c.customer_id AND u.day={d}
    WHERE s.status='subscribed' AND s.plan='A'
    GROUP BY c.group_id,c.customer_type""")
last = json.loads(Path('ceo_last_public.json').read_text())
assert last['day'] == d
quality = {}
for line in last['dashboard'].splitlines():
    p = line.split()
    if len(p) >= 5 and p[0] in {r['group_id'] for r in rows}:
        quality[p[0]] = {'A': float(p[1]), 'B': float(p[2]), 'C': float(p[3])}
for r in rows:
    r['delivered_quality'] = quality.get(r['group_id'])
    r['current_monthly_contribution'] = r['mrr'] - r['current_daily_cost'] * 30
    r['daily_cost_changes'] = {
        quota: round(r[f'proposed_daily_cost_q{quota}'] - r['current_daily_cost'])
        for quota in [30, 35, 40, 45, 50]
    }
print(json.dumps({'day': d, 'current_A_tier': config['tier_A'],
                  'current_A_quota': config['quota_A'], 'groups': rows}, indent=2))
"
  }
}

