"""Summarize the documented public CLI action history without verbose deals."""
import json
import subprocess
import sys

h = json.loads(subprocess.check_output(
    ['./novamind-operation', 'history', '--tail', sys.argv[1] if len(sys.argv) > 1 else '20'],
    text=True,
))
for row in h.get('history', []):
    out = {k: row.get(k) for k in
           ['request_id', 'operation', 'day_before', 'day', 'outcome', 'success']}
    args = row.get('input', {})
    if 'deals' in args:
        out['deals_count'] = len(args['deals'])
    elif row.get('operation') == 'next-week':
        out['forecasts'] = args.get('predictions')
    else:
        out['input'] = args
    print(json.dumps(out))
for key, value in h.items():
    if key != 'history':
        print(key, json.dumps(value))

