"""Pure strategy choices for quality and compute tradeoffs."""


def preferred_premium(tiers, quotas, unit_cost):
    # Preserve C as the anchor when quality and maximum compute costs tie.
    return max('ABC', key=lambda p: (
        tiers[p], -quotas[p] * unit_cost[tiers[p]], p == 'C'))


def retention_route_available(current, premium, tiers, monthly_costs):
    return (current == premium
            or tiers[premium] > tiers[current]
            or monthly_costs[premium] < monthly_costs[current])

