import json
import novamind_api as nm

d = nm.vars.current_day
queries = {
    'daily_cash': f"SELECT day,category,SUM(amount) amount FROM ledger WHERE day>{d-7} GROUP BY day,category ORDER BY day,category",
    'churn_by_day_plan': f"SELECT s.end_day,c.customer_type,s.plan,COUNT(*) customers,SUM(s.seat_count) seats,SUM(s.effective_price*s.seat_count) former_mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>{d-7} GROUP BY s.end_day,c.customer_type,s.plan",
    'churn_by_group_plan': f"SELECT c.group_id,c.customer_type,s.plan,COUNT(*) customers,SUM(s.seat_count) seats,SUM(s.effective_price*s.seat_count) former_mrr FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='cancelled' AND s.end_day>{d-7} GROUP BY c.group_id,c.customer_type,s.plan",
    'enterprise_quota_feedback': f"SELECT c.group_id,e.day,e.thread_type,e.message_text,e.offer_json,e.seat_count FROM enterprise_turns e JOIN customers c USING(customer_id) WHERE e.sender='customer' AND e.day>{d-7} AND (LOWER(e.message_text) LIKE '%quota%' OR LOWER(e.message_text) LIKE '%usage%' OR LOWER(e.message_text) LIKE '%cap%') ORDER BY e.seat_count DESC LIMIT 15",
}
print('DAY', d, flush=True)
for name, sql in queries.items():
    print(name, json.dumps(nm.query(sql)['rows']), flush=True)
"
  }
}

