            if r['thread_type'] in ('churn_prevention','renewal') and retention_route_available(r['plan'],premium_plan,tiers,{plan:monthly_compute(r['group_id'],plan) for plan in 'ABC'}):
                premium=next((o for o in p['offers'].get(r['group_id'],[]) if o[0]==premium_plan),None)
                if 'premium_limits' in p:
                    ceiling=p['premium_limits'].get(r['group_id'])
                    premium=[premium_plan,ceiling] if ceiling else None
                elif premium is None:
                    budget=cache.get(r['group_id'],{}).get('data',{}).get('estimates',{}).get('willingness_to_pay',0)
                    premium=[premium_plan,budget*.85] if budget else None
                if premium and r['plan']!=premium_plan and not any(o[0]==premium_plan for o in offers):
                    current_margin=max(o[1]-monthly_compute(r['group_id'],o[0]) for o in offers)
                    price=round(max(minimum_price(r['group_id'],premium_plan),current_margin+monthly_compute(r['group_id'],premium_plan)+2),2)
                    old_gap=p.get('quality_gaps',{}).get(r['group_id'],{}).get(r['plan'],10)
                    if old_gap<.5:
                        price=min(price,premium[1])
                    if minimum_price(r['group_id'],premium_plan)<=price<=premium[1]:
                        offers.append([premium_plan,price])
                elif r['plan']==premium_plan and any(o[0]==premium_plan for o in offers):
                    price=next(o[1] for o in offers if o[0]==premium_plan)
