def terminal_upfront_factor(day, billing_mod30, end_day=500, reply_window=7):
    """Discount only against initial cash; do not rely on future renewals.

    Taking the worst acceptance day protects every reply timing in the window.
    A result below1 implies the initial payment covers the entire remaining run.
    """
    factors = []
    for accept_day in range(day + 1, min(day + reply_window, end_day) + 1):
        initial_days = (billing_mod30 - accept_day) % 30 or 30
        factors.append((end_day - accept_day + 1) / initial_days)
    return min(1.0, max(factors, default=1.0))

