 if m:actual[r['day']]=float(m[1].replace(',',''))
rows=nm.query(f"SELECT submit_day,predicted_value,predicted_lower,predicted_upper FROM predictions WHERE metric='cash' AND horizon_days=7 AND submit_day>={D-56} AND submit_day+7<={D} ORDER BY submit_day")['rows']
out=[]
for r in rows:
 if r['submit_day']+7 in actual:
  a=actual[r['submit_day']+7];out.append(r|{'actual':a,'error':a-r['predicted_value']})
recent=[r['error'] for r in out if r['submit_day']>=434]
print(json.dumps({'day':D,'forecasts':out,'recent_bias':sum(recent)/len(recent) if recent else None,'recent_rmse':math.sqrt(sum(e*e for e in recent)/len(recent)) if recent else None}))

