def counter_price_floor(day, thread_type, billing_mod30, full_floor,
                        quota, unit_cost, hard_minimum):
    """New-lead-only discount funded by initial cash at full quota usage."""
    import math
    if day < 476 or thread_type != 'new_lead' or billing_mod30 is None:
        return full_floor
    factor = terminal_upfront_factor(day, billing_mod30)
    raw = max(hard_minimum, quota * 30 * unit_cost * 1.15 * factor)
    return min(full_floor, math.ceil(raw * 100 - 1e-9) / 100)

